package com.nexodb.ui;

import static com.nexodb.util.I18n.tr;
import com.nexodb.tools.SqlProjectService;
import com.nexodb.util.SqlFiles;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.event.*;
import javax.swing.tree.*;
import java.awt.*;
import java.awt.event.*;
import java.nio.file.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.function.Consumer;

/** Local SQL project workspace with safe file editing and command-based Git integration. */
public final class SqlProjectPanel extends JPanel {
    private record ProjectNode(Path relative,boolean directory,String state){@Override public String toString(){if(relative==null)return "";Path name=relative.getFileName();return name==null?relative.toString():name.toString();}}
    private final SqlProjectService project;private final Consumer<Path> queryOpener;
    private final DefaultMutableTreeNode rootNode=new DefaultMutableTreeNode();private final DefaultTreeModel treeModel=new DefaultTreeModel(rootNode);private final JTree tree=new JTree(treeModel);
    private final SqlEditorPane editor=new SqlEditorPane();private final JTextArea diff=new JTextArea(),history=new JTextArea();private final JTabbedPane details=new JTabbedPane();
    private final JLabel status=new JLabel(" "),branch=new JLabel();private final JButton save=button("Guardar"),openQuery=button("Abrir en consulta"),refresh=button("Actualizar"),stage=button("Preparar"),unstage=button("Quitar de preparados");
    private Path current;private String diskHash="";private boolean loading,dirty,busy;

    public SqlProjectPanel(SqlProjectService project,Consumer<Path> queryOpener){
        super(new BorderLayout(6,6));this.project=project;this.queryOpener=queryOpener;setBorder(new EmptyBorder(8,8,8,8));
        JToolBar files=new JToolBar();files.setFloatable(false);files.add(new JLabel(project.name()+"   "));files.add(button("Nuevo SQL",this::newSql));files.add(button("Nueva carpeta",this::newFolder));files.add(button("Renombrar",this::rename));files.add(button("Eliminar",this::delete));files.add(refresh);files.addSeparator();files.add(save);files.add(openQuery);add(files,BorderLayout.NORTH);
        tree.setRootVisible(true);tree.setShowsRootHandles(true);tree.setCellRenderer(new Renderer());tree.addTreeSelectionListener(e->selectionChanged());tree.addMouseListener(new MouseAdapter(){public void mouseClicked(MouseEvent e){if(e.getClickCount()==2)openSelected();}});
        editor.getDocument().addDocumentListener(new DocumentListener(){private void changed(){if(!loading){dirty=true;updateActions();}}public void insertUpdate(DocumentEvent e){changed();}public void removeUpdate(DocumentEvent e){changed();}public void changedUpdate(DocumentEvent e){}});
        int shortcut=GraphicsEnvironment.isHeadless()?KeyEvent.CTRL_DOWN_MASK:Toolkit.getDefaultToolkit().getMenuShortcutKeyMaskEx();editor.getInputMap().put(KeyStroke.getKeyStroke(KeyEvent.VK_S,shortcut),"save-project-sql");editor.getActionMap().put("save-project-sql",new AbstractAction(){public void actionPerformed(ActionEvent e){save();}});
        diff.setEditable(false);history.setEditable(false);diff.setFont(new Font(Font.MONOSPACED,Font.PLAIN,13));history.setFont(diff.getFont());details.addTab("SQL",new JScrollPane(editor));details.addTab(tr("Cambios Git"),new JScrollPane(diff));details.addTab(tr("Historial Git"),new JScrollPane(history));JSplitPane split=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,new JScrollPane(tree),details);split.setDividerLocation(285);split.setResizeWeight(.18);add(split);
        JToolBar git=new JToolBar();git.setFloatable(false);git.add(new JLabel("Git: "));git.add(branch);git.addSeparator();git.add(button("Inicializar Git",this::initGit));git.add(stage);git.add(unstage);git.add(button("Preparar todo",this::stageAll));git.add(button("Commit…",this::commit));git.add(button("Identidad Git…",this::identity));git.add(button("Ver historial",this::loadHistory));JPanel footer=new JPanel(new BorderLayout(6,4));footer.add(git,BorderLayout.NORTH);footer.add(status);add(footer,BorderLayout.SOUTH);
        refresh.addActionListener(e->refresh());save.addActionListener(e->save());openQuery.addActionListener(e->openInQuery());stage.addActionListener(e->gitForSelected(true));unstage.addActionListener(e->gitForSelected(false));refresh();
    }
    public Path root(){return project.root();}
    public boolean canClose(){if(!dirty)return true;Object[] options={tr("Guardar"),tr("Descartar"),tr("Cancelar")};int answer=JOptionPane.showOptionDialog(this,tr("Hay cambios sin guardar en ")+current+".",tr("Cerrar proyecto SQL"),JOptionPane.DEFAULT_OPTION,JOptionPane.WARNING_MESSAGE,null,options,options[0]);if(answer==0)return save();return answer==1;}
    private static JButton button(String text){return UiLanguage.text(new JButton(tr(text)),UiLanguage.key(text));}
    private static JButton button(String text,Runnable action){JButton button=button(text);button.addActionListener(e->action.run());return button;}
    private void updateActions(){boolean file=current!=null&&!busy;save.setEnabled(file&&dirty);openQuery.setEnabled(file);ProjectNode selected=selected();boolean selection=selected!=null&&selected.relative()!=null&&!selected.relative().toString().isBlank();stage.setEnabled(selection&&project.isGitRepository());unstage.setEnabled(selection&&project.isGitRepository());editor.setEditable(file&&!busy);}
    private ProjectNode selected(){TreePath path=tree.getSelectionPath();if(path==null)return null;Object value=((DefaultMutableTreeNode)path.getLastPathComponent()).getUserObject();return value instanceof ProjectNode node?node:null;}
    private void selectionChanged(){ProjectNode node=selected();if(node!=null&&!node.directory())load(node.relative());}
    private void openSelected(){ProjectNode node=selected();if(node!=null&&!node.directory())load(node.relative());}
    private boolean leaveCurrent(){if(!dirty)return true;int answer=JOptionPane.showConfirmDialog(this,tr("Guardar los cambios de ")+current+"?",tr("Proyecto SQL"),JOptionPane.YES_NO_CANCEL_OPTION,JOptionPane.WARNING_MESSAGE);if(answer==JOptionPane.CANCEL_OPTION||answer==JOptionPane.CLOSED_OPTION)return false;return answer!=JOptionPane.YES_OPTION||save();}
    private void load(Path relative){if(Objects.equals(relative,current)||!leaveCurrent())return;setBusy(true,tr("Abriendo ")+relative+"…");new SwingWorker<SqlFiles.Loaded,Void>(){protected SqlFiles.Loaded doInBackground()throws Exception{return project.read(relative);}protected void done(){try{SqlFiles.Loaded loaded=get();current=project.root().relativize(loaded.path());diskHash=loaded.diskHash();loading=true;editor.restoreText(loaded.text());editor.setCaretPosition(0);loading=false;dirty=false;details.setSelectedIndex(0);status.setText(tr("Archivo abierto: ")+current);}catch(Exception error){showError(rootCause(error));}finally{loading=false;setBusy(false,null);updateActions();}}}.execute();}
    private boolean save(){if(current==null||busy)return false;try{Path target=project.root().resolve(current);if(!diskHash.isBlank()&&Files.exists(target)&&!SqlFiles.diskHash(target).equals(diskHash)){int answer=JOptionPane.showConfirmDialog(this,tr("El archivo cambió fuera de AdisDB. ¿Sobrescribirlo con el contenido del editor?"),tr("Conflicto de archivo"),JOptionPane.YES_NO_OPTION,JOptionPane.WARNING_MESSAGE);if(answer!=JOptionPane.YES_OPTION)return false;}diskHash=project.write(current,editor.getText());dirty=false;status.setText(tr("Guardado: ")+current);updateActions();refresh();return true;}catch(Exception error){showError(error);return false;}}
    private void openInQuery(){if(current==null||dirty&&!save())return;queryOpener.accept(project.root().resolve(current));}
    private void refresh(){setBusy(true,tr("Leyendo proyecto y estado Git…"));new SwingWorker<List<SqlProjectService.Entry>,Void>(){protected List<SqlProjectService.Entry> doInBackground()throws Exception{return project.entries();}protected void done(){try{List<SqlProjectService.Entry> entries=get();rebuild(entries);branch.setText(project.isGitRepository()?Objects.toString(project.branch(),tr("sin rama")):tr("no inicializado"));if(current!=null&&project.isGitRepository())loadDiff(current);status.setText(entries.size()+tr(" elementos · ")+project.root());}catch(Exception error){showError(rootCause(error));}finally{setBusy(false,null);}}}.execute();}
    private void rebuild(List<SqlProjectService.Entry> entries){rootNode.removeAllChildren();rootNode.setUserObject(new ProjectNode(Path.of(""),true,""));Map<Path,DefaultMutableTreeNode> nodes=new HashMap<>();nodes.put(Path.of(""),rootNode);for(SqlProjectService.Entry entry:entries){Path relative=entry.relative(),parent=relative.getParent()==null?Path.of(""):relative.getParent();DefaultMutableTreeNode parentNode=ensureDirectory(parent,nodes);DefaultMutableTreeNode node=nodes.get(relative);if(node==null){node=new DefaultMutableTreeNode(new ProjectNode(relative,entry.directory(),entry.gitStatus()));nodes.put(relative,node);parentNode.add(node);}else node.setUserObject(new ProjectNode(relative,entry.directory(),entry.gitStatus()));}treeModel.reload();for(int i=0;i<tree.getRowCount();i++)tree.expandRow(i);selectCurrent();}
    private DefaultMutableTreeNode ensureDirectory(Path path,Map<Path,DefaultMutableTreeNode> nodes){DefaultMutableTreeNode existing=nodes.get(path);if(existing!=null)return existing;Path parent=path.getParent()==null?Path.of(""):path.getParent();DefaultMutableTreeNode node=new DefaultMutableTreeNode(new ProjectNode(path,true,""));ensureDirectory(parent,nodes).add(node);nodes.put(path,node);return node;}
    private void selectCurrent(){if(current==null)return;Enumeration<?> all=rootNode.depthFirstEnumeration();while(all.hasMoreElements()){DefaultMutableTreeNode node=(DefaultMutableTreeNode)all.nextElement();if(node.getUserObject() instanceof ProjectNode value&&current.equals(value.relative())){tree.setSelectionPath(new TreePath(node.getPath()));return;}}}
    private Path folderForNew(){ProjectNode node=selected();if(node==null||node.relative()==null)return Path.of("");return node.directory()?node.relative():Objects.requireNonNullElse(node.relative().getParent(),Path.of(""));}
    private void newSql(){if(!LicenseGate.ensure(this))return;String name=JOptionPane.showInputDialog(this,tr("Nombre del nuevo archivo SQL:"),"consulta.sql");if(name==null)return;try{Path created=project.createSql(folderForNew().resolve(name));refresh();load(created);}catch(Exception error){showError(error);}}
    private void newFolder(){if(!LicenseGate.ensure(this))return;String name=JOptionPane.showInputDialog(this,tr("Nombre de la nueva carpeta:"),"scripts");if(name==null)return;try{project.createFolder(folderForNew().resolve(name));refresh();}catch(Exception error){showError(error);}}
    private void rename(){ProjectNode node=selected();if(node==null||node.relative()==null||node.relative().toString().isBlank()||!leaveCurrent())return;String name=JOptionPane.showInputDialog(this,tr("Nuevo nombre:"),node.relative().getFileName());if(name==null)return;try{Path old=node.relative(),renamed=project.rename(old,name);if(old.equals(current)){current=renamed;diskHash=SqlFiles.diskHash(project.root().resolve(renamed));}refresh();}catch(Exception error){showError(error);}}
    private void delete(){ProjectNode node=selected();if(node==null||node.relative()==null||node.relative().toString().isBlank())return;if(node.relative().equals(current)&&!leaveCurrent())return;if(!Confirmations.ask(this,"Eliminar del proyecto",node.relative()+"\n"+tr("Esta acción elimina el archivo local. Git podrá recuperarlo si ya tenía un commit. ¿Continuar?")))return;try{project.delete(node.relative());if(node.relative().equals(current)){current=null;diskHash="";dirty=false;loading=true;editor.restoreText("");loading=false;}refresh();updateActions();}catch(Exception error){showError(error);}}
    private void initGit(){if(!LicenseGate.ensure(this))return;runGit(tr("Inicializando Git…"),project::initGit,true);}
    private void gitForSelected(boolean add){ProjectNode node=selected();if(node==null||node.relative()==null||node.relative().toString().isBlank())return;runGit(add?tr("Preparando cambio…"):tr("Quitando de preparados…"),()->add?project.stage(node.relative()):project.unstage(node.relative()),true);}
    private void stageAll(){runGit(tr("Preparando cambios…"),project::stageAll,true);}
    private void commit(){if(!LicenseGate.ensure(this))return;String message=JOptionPane.showInputDialog(this,tr("Mensaje del commit:"));if(message==null)return;runGit(tr("Creando commit…"),()->{SqlProjectService.GitResult staged=project.stageAll();return staged.ok()?project.commit(message):staged;},true);}
    private void identity(){JTextField name=new JTextField(),email=new JTextField();JPanel form=new JPanel(new GridLayout(0,2,8,8));form.add(new JLabel(tr("Nombre")));form.add(name);form.add(new JLabel(tr("Correo")));form.add(email);if(JOptionPane.showConfirmDialog(this,form,tr("Identidad Git del proyecto"),JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;runGit(tr("Guardando identidad Git…"),()->project.configureIdentity(name.getText(),email.getText()),false);}
    private void loadDiff(Path relative){if(!project.isGitRepository())return;runText(tr("Leyendo diferencias…"),()->project.diff(relative),text->{diff.setText(text.isBlank()?tr("Sin cambios para este archivo."):text);diff.setCaretPosition(0);});}
    private void loadHistory(){if(!project.isGitRepository()){status.setText(tr("Inicializa Git primero."));return;}ProjectNode node=selected();Path relative=node!=null&&!node.directory()?node.relative():null;runText(tr("Leyendo historial…"),()->project.history(relative),text->{history.setText(text.isBlank()?tr("Todavía no hay commits."):text);history.setCaretPosition(0);details.setSelectedIndex(2);});}
    private void runGit(String message,Callable<SqlProjectService.GitResult> work,boolean reload){setBusy(true,message);new SwingWorker<SqlProjectService.GitResult,Void>(){protected SqlProjectService.GitResult doInBackground()throws Exception{return work.call();}protected void done(){boolean refreshAfter=false;try{SqlProjectService.GitResult result=get();status.setText(result.output().isBlank()?(result.ok()?tr("Operación Git completada."):tr("Git no completó la operación.")):result.output());if(!result.ok())JOptionPane.showMessageDialog(SqlProjectPanel.this,result.output(),tr("Git"),JOptionPane.WARNING_MESSAGE);refreshAfter=reload;}catch(Exception error){showError(rootCause(error));}finally{setBusy(false,null);if(refreshAfter)refresh();}}}.execute();}
    private void runText(String message,Callable<String> work,Consumer<String> done){setBusy(true,message);new SwingWorker<String,Void>(){protected String doInBackground()throws Exception{return work.call();}protected void done(){try{done.accept(get());}catch(Exception error){showError(rootCause(error));}finally{setBusy(false,null);}}}.execute();}
    private void setBusy(boolean value,String message){busy=value;if(message!=null)status.setText(message);tree.setEnabled(!value);refresh.setEnabled(!value);updateActions();}
    private void showError(Throwable error){status.setText(error.getMessage());JOptionPane.showMessageDialog(this,error.getMessage(),tr("Proyecto SQL"),JOptionPane.ERROR_MESSAGE);}
    private static Throwable rootCause(Throwable error){Throwable result=error;while(result.getCause()!=null&&result.getCause()!=result)result=result.getCause();return result;}
    private final class Renderer extends DefaultTreeCellRenderer{public Component getTreeCellRendererComponent(JTree tree,Object value,boolean selected,boolean expanded,boolean leaf,int row,boolean focus){JLabel label=(JLabel)super.getTreeCellRendererComponent(tree,value,selected,expanded,leaf,row,focus);Object user=((DefaultMutableTreeNode)value).getUserObject();if(user instanceof ProjectNode node){String state=node.state(),caption=node.relative()!=null&&node.relative().toString().isBlank()?project.name():node.toString();label.setText(caption+(state.isBlank()?"":"   ["+state+"]"));label.setIcon(IconFactory.of(node.directory()?IconFactory.Kind.FOLDER:IconFactory.Kind.SQL,16));if(!selected&&!state.isBlank())label.setForeground(state.contains("?")?ThemeManager.color(0xB45309,0xFBBF24):ThemeManager.color(0xB91C1C,0xFCA5A5));}return label;}}
}
